#!/usr/bin/env python3
"""SEAT S34 — oracle checker for the independent souji-verify review harness.

Reads $LAB/cases.tsv (expectations derived from the binding spec only) and the
tool's captured runs, grades every case, and emits a JSON fragment on stdout.
"""
import json
import os
import re
import sys

LAB = sys.argv[1]
RUNS = os.path.join(LAB, "runs")
CASES = os.path.join(LAB, "cases.tsv")

SAFE_RECEIPTS = {"pushed", "moved-to-obsidian", "stale", "metadata-prune"}


def read(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            return fh.read()
    except FileNotFoundError:
        return ""


def read_rc(name):
    txt = read(os.path.join(RUNS, name + ".rc")).strip()
    return int(txt) if txt.isdigit() else None


def parse_plain(name):
    lines = []
    for raw in read(os.path.join(RUNS, name + ".out")).splitlines():
        if not raw.strip():
            continue
        fields = raw.split("\t")
        if len(fields) >= 5 and fields[0] == "VERDICT":
            lines.append({
                "path": fields[1],
                "verdict": fields[2],
                "receipt": fields[3],
                "evidence": "\t".join(fields[4:]),
                "raw": raw,
            })
        else:
            lines.append({"malformed": True, "raw": raw})
    return lines


def index_by_path(lines):
    idx = {}
    for ln in lines:
        if ln.get("malformed"):
            continue
        idx.setdefault(ln["path"], ln)
    return idx


def rx(pattern, text):
    if not pattern:
        return True
    return re.search(pattern, text) is not None


def parse_alt(alt):
    """alt format: VERDICT:regex, or empty."""
    if not alt:
        return None
    if ":" in alt:
        v, r = alt.split(":", 1)
        return v, r
    return None


def grade_case(row, idx):
    cid, kind, path, exp3, p4, alt, notes = row
    got = idx.get(path)
    obs = None if got is None else {
        "verdict": got.get("verdict"),
        "receipt": got.get("receipt"),
        "evidence": got.get("evidence"),
        "raw": got.get("raw"),
    }
    if kind == "info":
        return {"id": cid, "kind": kind, "path": path, "notes": notes,
                "observed": obs, "grade": "info"}
    if got is None:
        return {"id": cid, "kind": kind, "path": path, "notes": notes,
                "expected": {"verdict": exp3, "receipt": p4, "alt": alt},
                "observed": None, "grade": "fail", "why": "no output line for target"}

    verdict = got["verdict"]
    receipt = got["receipt"]
    evidence = got["evidence"]
    altspec = parse_alt(alt)

    if kind == "dual":
        primary = verdict == exp3 and rx(p4, receipt)
        alt_ok = bool(altspec) and verdict == altspec[0] and rx(altspec[1], receipt)
        if primary and alt_ok:
            reading = "both"
        elif primary:
            reading = "primary:" + exp3 + "(" + receipt + ")"
        elif alt_ok:
            reading = "alt:" + altspec[0] + "(" + receipt + ")"
        else:
            reading = "neither"
        return {"id": cid, "kind": kind, "path": path, "notes": notes,
                "expected": {"verdict": exp3, "receipt": p4, "alt": alt},
                "observed": obs,
                "grade": "pass" if (primary or alt_ok) else "fail",
                "reading": reading}

    if kind in ("special_p4", "special_p5"):
        m = re.search(r"unpushed=(\d+)\s+dirty=(\d+)", got["raw"])
        if kind == "special_p4":
            ok_verdict = verdict == "NOT-SAFE"
            ok_nums = bool(m) and int(m.group(1)) == 1 and int(m.group(2)) >= 1
        else:
            ok_verdict = verdict == "NOT-SAFE"
            ok_nums = bool(m) and int(m.group(1)) == 0 and int(m.group(2)) == 0
        grade = "pass" if (ok_verdict and ok_nums) else ("fail" if not ok_verdict else "minor")
        return {"id": cid, "kind": kind, "path": path, "notes": notes,
                "expected": {"verdict": exp3, "counts": "unpushed/dirty as spec'd"},
                "observed": obs,
                "counts": {"unpushed": int(m.group(1)) if m else None,
                           "dirty": int(m.group(2)) if m else None},
                "grade": grade}

    # kind == case
    ok_verdict = verdict == exp3
    ok_receipt = rx(p4, receipt) or (bool(altspec) and verdict == altspec[0] and rx(altspec[1], receipt))
    ok_evidence = bool(evidence and evidence.strip())
    if ok_verdict and ok_receipt and ok_evidence:
        grade = "pass"
    elif ok_verdict and ok_evidence:
        grade = "minor"
    else:
        grade = "fail"
    return {"id": cid, "kind": kind, "path": path, "notes": notes,
            "expected": {"verdict": exp3, "receipt": p4, "alt": alt},
            "observed": obs, "grade": grade}


def main():
    rows = []
    for line in read(CASES).splitlines():
        if not line.strip():
            continue
        fields = line.split("\t")
        while len(fields) < 7:
            fields.append("")
        rows.append(fields[:7])

    batch1 = parse_plain("batch1")
    idx = index_by_path(batch1)
    malformed = [ln for ln in batch1 if ln.get("malformed")]

    results = [grade_case(r, idx) for r in rows]
    counts = {"pass": 0, "minor": 0, "fail": 0, "info": 0}
    for r in results:
        counts[r["grade"]] = counts.get(r["grade"], 0) + 1

    # every graded line must carry non-empty decisive evidence
    empty_evidence = [r["id"] for r in results
                      if r["grade"] in ("pass", "minor", "fail") and r["observed"]
                      and not (r["observed"].get("evidence") or "").strip()]
    unknown_safe = sorted({r["observed"]["receipt"] for r in results
                           if r["observed"] and r["observed"].get("verdict") == "SAFE"
                           and r["observed"].get("receipt") not in SAFE_RECEIPTS})

    # --stale-days 30: 2-day-old scratch must no longer be stale
    b30 = index_by_path(parse_plain("batch30"))
    b30_checks = []
    for path, want_v, want_r in [
        (os.path.join(LAB, "fleet/scratch/stale-probe-r34.out"), "NOT-SAFE", None),
        (os.path.join(LAB, "fleet/scratch/fresh-probe-r34.out"), "NOT-SAFE", None),
        (os.path.join(LAB, "fleet/scratch/doc-r34-draft.md"), "NOT-SAFE", None),
        (os.path.join(LAB, "repos/p1/docs/fileA.txt"), "SAFE", "pushed"),
    ]:
        got = b30.get(path)
        ok = bool(got) and got["verdict"] == want_v and (want_r is None or got["receipt"] == want_r)
        b30_checks.append({"path": path, "want": {"verdict": want_v, "receipt": want_r},
                           "observed": None if not got else {"verdict": got["verdict"], "receipt": got["receipt"]},
                           "pass": ok})

    # --json: parseable, verdict/receipt parity with batch1
    json_lines = [l for l in read(os.path.join(RUNS, "batchjson.out")).splitlines() if l.strip()]
    json_ok = True
    json_rows = []
    for line in json_lines:
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            json_ok = False
            json_rows.append({"parse": False, "raw": line[:200]})
            continue
        ref = idx.get(obj.get("path"))
        parity = bool(ref) and ref["verdict"] == obj.get("verdict") and ref["receipt"] == obj.get("receipt")
        json_rows.append({"parse": True, "path": obj.get("path"), "verdict": obj.get("verdict"),
                          "receipt": obj.get("receipt"), "parity_with_batch1": parity})
        json_ok = json_ok and parity

    # determinism: identical stdout across two runs
    det = read(os.path.join(RUNS, "batch1.out")) == read(os.path.join(RUNS, "batch1_repeat.out"))

    # CLI exit codes
    cli = {name: read_rc(name) for name in
           ["batch1", "noargs", "sd_noval", "sd_bad", "sd_eq_bad", "bogus", "batch30", "batchjson"]}
    cli_expected = {"batch1": 0, "noargs": 2, "sd_noval": 2, "sd_bad": 2,
                    "sd_eq_bad": 2, "bogus": 2, "batch30": 0, "batchjson": 0}
    cli_ok = {k: cli.get(k) == v for k, v in cli_expected.items()}

    fragment = {
        "lab": LAB,
        "cases_total": len(rows),
        "bucket_counts": counts,
        "malformed_lines": len(malformed),
        "empty_evidence": empty_evidence,
        "unknown_safe_receipts": unknown_safe,
        "cases": results,
        "stale_days_30": b30_checks,
        "json_mode": {"all_parsed_and_parity": json_ok, "rows": json_rows},
        "determinism_identical": det,
        "cli_exit_codes": {"expected": cli_expected, "observed": cli, "ok": cli_ok},
    }
    print(json.dumps(fragment, indent=1))
    print("\nSUMMARY pass=%d minor=%d fail=%d info=%d malformed=%d determinism=%s json=%s"
          % (counts.get("pass", 0), counts.get("minor", 0), counts.get("fail", 0),
             counts.get("info", 0), len(malformed), det, json_ok))


if __name__ == "__main__":
    main()
